package runtime

import (
	"testing"
)

// Paper §3.3.2 conformance (Definitions 31-35):
//   - Lemma 32/33: ≃ₖ and ≃_S are equivalence relations (reflexive, symmetric,
//     transitive), key by key;
//   - Def 31: ≃ₖ is generated by the key's OBSERVATIONS — fields outside the
//     observation boundary are NOT distinguishable (compare behavior, not
//     representation);
//   - Def 33: ≃_S compares dom(σ)∩S and the per-key values only;
//   - "respect": operations at a key cannot distinguish ≃ₖ-related values.
//
// These tests exercise the MODEL over real RuntimeSnapshot observations.

func TestObservationEquivalenceIsEquivalenceRelation(t *testing.T) {
	// A model that observes availability + namespace (but not owner generation).
	key := "pa"
	m := NewObservationModel(ObservationSpec{
		Key: key,
		Fields: map[ObservedField]bool{
			ObserveAvailability: true, ObserveNamespace: true,
		},
	})

	// Build three snapshots that are equivalent at `key` but differ in an
	// unobserved field (owner generation and activation counters).
	base := RuntimeSnapshot{Providers: []ProviderView{{
		Key: key, State: StateActive, Retiring: false,
		OwnerFiberID: 1, OwnerActivationID: 1, ScopeID: 7,
	}}}
	sameAvailDifferentGen := RuntimeSnapshot{Providers: []ProviderView{{
		Key: key, State: StateActive, Retiring: false,
		OwnerFiberID: 99, OwnerActivationID: 42, ScopeID: 7,
	}}}
	differentNamespace := RuntimeSnapshot{Providers: []ProviderView{{
		Key: key, State: StateActive, Retiring: false,
		OwnerFiberID: 1, OwnerActivationID: 1, ScopeID: 8,
	}}}

	// Reflexive (Lemma 33: each ≃ₖ is an equivalence).
	if !m.EquivalentAt(base, base, nil) {
		t.Fatal("≃_S not reflexive")
	}
	// Symmetric: unobserved generation change relates both ways.
	if !m.EquivalentAt(base, sameAvailDifferentGen, nil) ||
		!m.EquivalentAt(sameAvailDifferentGen, base, nil) {
		t.Fatal("≃_S not symmetric over equivalent values")
	}
	// Transitive.
	third := RuntimeSnapshot{Providers: []ProviderView{{
		Key: key, State: StateActive, Retiring: false,
		OwnerFiberID: 7, OwnerActivationID: 8, ScopeID: 7,
	}}}
	if !m.EquivalentAt(base, sameAvailDifferentGen, nil) ||
		!m.EquivalentAt(sameAvailDifferentGen, third, nil) ||
		!m.EquivalentAt(base, third, nil) {
		t.Fatal("≃_S not transitive")
	}
	// Observed difference (namespace) is NOT erased — "coarsest respected".
	if m.EquivalentAt(base, differentNamespace, nil) {
		t.Fatal("≃_S erased an OBSERVED difference (namespace)")
	}
}

func TestObservationEquivalenceDomainIntersection(t *testing.T) {
	// Def 33: σ ≃_S σ' requires dom(σ)∩S = dom(σ')∩S.
	m := NewObservationModel() // minimal default boundary
	onlyA := RuntimeSnapshot{Providers: []ProviderView{{
		Key: "a", State: StateActive, OwnerFiberID: 1, OwnerActivationID: 1,
	}}}
	aAndB := RuntimeSnapshot{Providers: []ProviderView{
		{Key: "a", State: StateActive, OwnerFiberID: 1, OwnerActivationID: 1},
		{Key: "b", State: StateActive, OwnerFiberID: 2, OwnerActivationID: 2},
	}}
	// Restrict S = {a}: b is outside the observation set -> related.
	if !m.EquivalentAt(onlyA, aAndB, []CapabilityKey{NewKey[string]("a").Capability()}) {
		t.Fatal("≃_{a} should forget keys outside S")
	}
	// Full set S = K: domains differ -> not related.
	if m.EquivalentAt(onlyA, aAndB, nil) {
		t.Fatal("≃ (full) must compare dom equality")
	}
}

func TestObservationEquivalenceRespectsOperations(t *testing.T) {
	// An operation at a key (provide/require) observes availability. Two
	// records equivalent at that key must be indistinguishable by that op:
	// both available or both not, regardless of hidden generation names.
	m := NewObservationModel(ObservationSpec{
		Key: "codec", Fields: map[ObservedField]bool{ObserveAvailability: true},
	})
	liveA := ProviderView{Key: "codec", State: StateActive, OwnerFiberID: 1, OwnerActivationID: 1}
	liveB := ProviderView{Key: "codec", State: StateActive, OwnerFiberID: 88, OwnerActivationID: 99}
	dead := ProviderView{Key: "codec", State: StateUnloading, Retiring: true, OwnerFiberID: 1, OwnerActivationID: 1}

	if !m.EquivalentValues("codec", liveA, liveB) {
		t.Fatal("operations at key must not distinguish equivalent availability")
	}
	if m.EquivalentValues("codec", liveA, dead) {
		t.Fatal("operations at key MUST distinguish availability differences")
	}
}

func TestObservationEquivalenceOwnerGenerationObservedWhenDeclared(t *testing.T) {
	// Dependency capture/withdrawal observes the provider GENERATION (Thm 70).
	// A key declaring ObserveOwnerGeneration must distinguish it.
	m := NewObservationModel(ObservationSpec{
		Key: "svc", Fields: map[ObservedField]bool{
			ObserveAvailability: true, ObserveOwnerGeneration: true,
		},
	})
	a := ProviderView{Key: "svc", State: StateActive, OwnerFiberID: 1, OwnerActivationID: 1}
	b := ProviderView{Key: "svc", State: StateActive, OwnerFiberID: 2, OwnerActivationID: 1}
	if m.EquivalentValues("svc", a, b) {
		t.Fatal("observed generation difference was erased")
	}
}
